    .dgs-performance-page,
    .dgs-performance-page * {
      box-sizing: border-box;
    }

    .dgs-performance-page {
      width: 100vw !important;
      max-width: 100vw !important;
      margin-left: calc(50% - 50vw) !important;
      margin-right: calc(50% - 50vw) !important;
      margin-top: 0 !important;
      padding-top: 0 !important;
      position: relative;
      overflow: hidden;
      font-family: Inter, Poppins, Arial, sans-serif;
      color: #ffffff;
      background:
        radial-gradient(circle at 10% 8%, rgba(56, 189, 248, 0.18), transparent 30%),
        radial-gradient(circle at 88% 15%, rgba(56, 189, 248, 0.14), transparent 32%),
        radial-gradient(circle at 52% 96%, rgba(139, 92, 246, 0.16), transparent 42%),
        linear-gradient(180deg, #020617 0%, #08111f 42%, #020617 100%) !important;
      isolation: isolate;
    }

    .dgs-performance-page a {
      text-decoration: none;
    }

    .dgs-bg-motion {
      position: absolute;
      inset: 0;
      pointer-events: none;
      z-index: 0;
      overflow: hidden;
    }

    .dgs-grid-motion {
      position: absolute;
      inset: 0;
      opacity: 0.10;
      background-image:
        linear-gradient(rgba(255,255,255,0.13) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.13) 1px, transparent 1px);
      background-size: clamp(54px, 3vw, 84px) clamp(54px, 3vw, 84px);
      mask-image: linear-gradient(to bottom, rgba(0,0,0,1), rgba(0,0,0,.72), transparent);
    }

    .dgs-glow {
      position: absolute;
      width: clamp(320px, 28vw, 680px);
      height: clamp(320px, 28vw, 680px);
      border-radius: 999px;
      filter: blur(100px);
      opacity: 0.22;
      mix-blend-mode: screen;
    }

    .dgs-glow.one {
      background: var(--dgs-blue);
      left: -12%;
      top: 2%;
    }

    .dgs-glow.two {
      background: var(--dgs-blue);
      right: -12%;
      top: 22%;
    }

    .dgs-glow.three {
      background: var(--dgs-purple);
      left: 38%;
      bottom: -16%;
    }

    .dgs-wrap {
      width: 100%;
      max-width: 2560px;
      margin: 0 auto;
      padding-left: clamp(22px, 5vw, 140px);
      padding-right: clamp(22px, 5vw, 140px);
      position: relative;
      z-index: 2;
    }

    .dgs-section {
      padding: clamp(78px, 6vw, 145px) 0;
      position: relative;
      z-index: 2;
    }

    .dgs-card {
      background:
        radial-gradient(circle at 18% 10%, rgba(56,189,248,0.13), transparent 36%),
        linear-gradient(145deg, rgba(15,23,42,0.94), rgba(2,6,23,0.82)) !important;
      border: 1px solid var(--dgs-border);
      box-shadow: var(--dgs-shadow);
      backdrop-filter: blur(22px);
    }

    .dgs-pill {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      margin: 0 0 24px;
      padding: clamp(9px, 0.7vw, 13px) clamp(14px, 0.95vw, 20px);
      border-radius: 999px;
      color: #e0f2fe;
      font-size: clamp(12px, 0.72vw, 15px);
      font-weight: 850;
      background: rgba(15,23,42,0.72);
      border: 1px solid rgba(148,163,184,0.24);
      backdrop-filter: blur(18px);
      text-align: left;
    }

    .dgs-pill::before {
      content: "";
      width: 9px;
      height: 9px;
      flex: 0 0 9px;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--dgs-blue), var(--dgs-blue));
      box-shadow: 0 0 18px rgba(56,189,248,0.95);
    }

    .dgs-heading {
      margin: 0;
      color: #ffffff;
      font-size: clamp(44px, 4.35vw, 104px);
      line-height: 1.02;
      letter-spacing: clamp(-3.5px, -0.14vw, -1px);
      font-weight: 950;
      text-align: left;
      max-width: 1180px;
    }

    .dgs-heading.medium {
      font-size: clamp(34px, 3.2vw, 76px);
      line-height: 1.06;
      letter-spacing: clamp(-2.5px, -0.12vw, -0.8px);
    }

    .dgs-gradient {
      background: linear-gradient(90deg, #ffffff 0%, #7dd3fc 35%, #c4b5fd 64%, #f0abfc 100%);
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
    }

    .dgs-copy {
      margin: 24px 0 0;
      max-width: 960px;
      color: var(--dgs-text);
      font-size: clamp(16px, 1vw, 22px);
      line-height: 1.78;
      text-align: left;
    }

    .dgs-buttons {
      display: flex;
      flex-wrap: wrap;
      gap: 16px;
      align-items: center;
      justify-content: flex-start;
      margin-top: 38px;
    }

    .dgs-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: clamp(52px, 3vw, 66px);
      padding: clamp(14px, 1vw, 20px) clamp(22px, 1.7vw, 36px);
      border-radius: 999px;
      font-size: clamp(14px, 0.86vw, 18px);
      font-weight: 900;
      transition: 0.35s ease;
      border: 1px solid transparent;
    }

    .dgs-btn.primary {
      color: #ffffff;
      background: linear-gradient(135deg, var(--dgs-blue), var(--dgs-purple), var(--dgs-blue));
      box-shadow: 0 24px 70px rgba(56,189,248,0.24);
    }

    .dgs-btn.secondary {
      color: #e0f2fe;
      background: rgba(15,23,42,0.72);
      border-color: rgba(148,163,184,0.24);
      backdrop-filter: blur(18px);
    }

    .dgs-btn:hover {
      transform: translateY(-5px);
      filter: brightness(1.08);
    }

    .dgs-premium-icon,
    .dgs-proof-icon {
      width: clamp(46px, 3vw, 64px);
      height: clamp(46px, 3vw, 64px);
      display: inline-flex;
      align-items: center;
      justify-content: center;
      border-radius: 18px;
      background:
        radial-gradient(circle at 28% 20%, rgba(255,255,255,.36), transparent 32%),
        linear-gradient(135deg, rgba(56,189,248,.34), rgba(139,92,246,.26), rgba(37,99,235,.24));
      border: 1px solid rgba(255,255,255,.18);
      box-shadow: inset 0 0 22px rgba(255,255,255,.08), 0 18px 42px rgba(56,189,248,.16);
      color: #ffffff;
    }

    .dgs-premium-icon svg,
    .dgs-proof-icon svg {
      width: 52%;
      height: 52%;
      stroke: currentColor;
      stroke-width: 2.3;
      fill: none;
      stroke-linecap: round;
      stroke-linejoin: round;
    }

    /* HEADER ISSUE FIX:
       This section does not touch your website header.
       It only gives the hero enough space below your existing DGS header. */
    .dgs-hero {
      min-height: calc(100vh - 90px);
      display: flex;
      align-items: center;
      padding: clamp(125px, 7vw, 165px) 0 clamp(80px, 5vw, 120px);
      position: relative;
      z-index: 2;
    }

    .dgs-hero-grid {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(520px, 0.9fr);
      align-items: center;
      gap: clamp(44px, 5vw, 112px);
      width: 100%;
    }

    .dgs-hero-content {
      max-width: 1180px;
      width: 100%;
      text-align: left;
      min-width: 0;
    }

    .dgs-hero-note {
      margin-top: 34px;
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 14px;
      max-width: 960px;
    }

    .dgs-hero-note-card {
      padding: 18px;
      border-radius: 22px;
      background: rgba(2,6,23,0.48);
      border: 1px solid rgba(148,163,184,0.18);
    }

    .dgs-hero-note-card strong {
      display: block;
      color: #ffffff;
      font-size: clamp(15px, 0.85vw, 18px);
      line-height: 1.3;
      margin-bottom: 6px;
    }

    .dgs-hero-note-card span {
      color: var(--dgs-muted);
      font-size: clamp(12px, 0.72vw, 15px);
      line-height: 1.45;
    }

    .dgs-hero-panel {
      position: relative;
      width: 100%;
      min-width: 0;
      padding: clamp(26px, 2.4vw, 56px);
      border-radius: var(--dgs-radius);
      overflow: hidden;
    }

    .dgs-hero-panel-shine {
      position: absolute;
      inset: 0;
      background: linear-gradient(120deg, transparent 0%, rgba(255,255,255,.08) 45%, transparent 60%);
      transform: translateX(-120%);
      opacity: 0.8;
      pointer-events: none;
    }

    .dgs-dashboard-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      margin-bottom: clamp(22px, 1.6vw, 34px);
      position: relative;
      z-index: 2;
    }

    .dgs-dashboard-title {
      color: #ffffff;
      font-size: clamp(20px, 1.25vw, 30px);
      line-height: 1.15;
      font-weight: 950;
      letter-spacing: -0.7px;
    }

    .dgs-live {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: #bbf7d0;
      background: rgba(34,197,94,0.14);
      border: 1px solid rgba(34,197,94,0.30);
      border-radius: 999px;
      padding: 8px 12px;
      font-size: clamp(11px, 0.65vw, 13px);
      font-weight: 900;
      white-space: nowrap;
    }

    .dgs-live::before {
      content: "";
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--dgs-green);
      box-shadow: 0 0 15px rgba(34,197,94,0.95);
    }

    .dgs-dashboard-shell {
      position: relative;
      z-index: 2;
      padding: 20px;
      border-radius: 34px;
      background: rgba(2,6,23,0.52);
      border: 1px solid rgba(148,163,184,0.18);
    }

    .dgs-bars {
      height: clamp(280px, 18vw, 420px);
      display: flex;
      align-items: end;
      gap: clamp(12px, 0.9vw, 18px);
    }

    .dgs-bars span {
      flex: 1;
      border-radius: 999px 999px 10px 10px;
      background: linear-gradient(to top, var(--dgs-blue), var(--dgs-purple), var(--dgs-blue));
      box-shadow: 0 0 28px rgba(56,189,248,0.22);
      transform-origin: bottom;
    }

    .dgs-bars span:nth-child(1) { height: 34%; }
    .dgs-bars span:nth-child(2) { height: 48%; }
    .dgs-bars span:nth-child(3) { height: 42%; }
    .dgs-bars span:nth-child(4) { height: 60%; }
    .dgs-bars span:nth-child(5) { height: 52%; }
    .dgs-bars span:nth-child(6) { height: 76%; }
    .dgs-bars span:nth-child(7) { height: 88%; }
    .dgs-bars span:nth-child(8) { height: 70%; }

    .dgs-authority-premium {
      margin-bottom: clamp(82px, 7vw, 160px);
    }

    .dgs-authority-top {
      display: grid;
      grid-template-columns: minmax(0, .95fr) minmax(360px, .75fr);
      gap: clamp(28px, 4vw, 86px);
      align-items: end;
      margin-bottom: clamp(38px, 4vw, 78px);
    }

    .dgs-authority-text {
      margin: 0;
      max-width: 760px;
    }

    .dgs-logo-strip {
      position: relative;
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: clamp(18px, 1.4vw, 30px);
      align-items: stretch;
      padding: clamp(26px, 2.2vw, 54px);
      border-radius: var(--dgs-radius);
      overflow: hidden;
    }

    .dgs-logo-strip::before {
      content: "";
      position: absolute;
      inset: 0;
      background:
        radial-gradient(circle at 12% 20%, rgba(56,189,248,0.18), transparent 30%),
        radial-gradient(circle at 88% 80%, rgba(37,99,235,0.14), transparent 34%);
      pointer-events: none;
    }

    .dgs-logo-item {
      position: relative;
      z-index: 2;
      height: clamp(170px, 9vw, 235px);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: clamp(18px, 1.25vw, 28px);
      border-radius: clamp(24px, 1.5vw, 34px);
      background:
        radial-gradient(circle at 50% 0%, rgba(255,255,255,0.14), transparent 42%),
        linear-gradient(145deg, rgba(15,23,42,0.94), rgba(2,6,23,0.78));
      border: 1px solid rgba(148,163,184,0.24);
      transition: 0.35s ease;
      overflow: hidden;
    }

    .dgs-logo-item:hover {
      transform: translateY(-8px);
      border-color: rgba(56,189,248,0.42);
      box-shadow: 0 28px 80px rgba(0,0,0,0.38);
    }

    .dgs-logo-plate {
      position: relative;
      z-index: 3;
      width: min(92%, 340px);
      height: clamp(112px, 6.8vw, 162px);
      display: flex;
      align-items: center;
      justify-content: center;
      background: #ffffff;
      border-radius: 26px;
      padding: 16px 22px;
      box-shadow: 0 22px 50px rgba(0,0,0,0.38), inset 0 0 0 1px rgba(15,23,42,0.08);
      overflow: hidden;
    }

    .dgs-logo-plate img {
      display: block !important;
      width: auto !important;
      height: auto !important;
      object-fit: contain !important;
      transform: none !important;
      filter: none !important;
      image-rendering: auto;
    }

    .dgs-logo-google .dgs-logo-plate img {
      max-width: 235px !important;
      max-height: 118px !important;
    }

    .dgs-logo-meta .dgs-logo-plate {
      width: min(96%, 360px) !important;
      height: clamp(124px, 7.2vw, 170px) !important;
      padding: 10px 14px !important;
    }

    .dgs-logo-meta .dgs-logo-plate img {
      width: 100% !important;
      max-width: 285px !important;
      height: auto !important;
      max-height: 118px !important;
      object-fit: contain !important;
      transform: none !important;
    }

    .dgs-logo-clutch .dgs-logo-plate {
      border-radius: 14px !important;
    }

    .dgs-logo-clutch .dgs-logo-plate img {
      max-width: 250px !important;
      max-height: 126px !important;
    }

    .dgs-logo-goodfirms .dgs-logo-plate img {
      max-width: 250px !important;
      max-height: 110px !important;
    }

    .dgs-proof-premium {
      display: grid;
      grid-template-columns: minmax(0, .82fr) minmax(620px, 1.18fr);
      gap: clamp(34px, 3.8vw, 82px);
      align-items: center;
      margin-bottom: clamp(82px, 7vw, 160px);
    }

    .dgs-proof-number-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: clamp(14px, 1vw, 22px);
      margin-top: 34px;
    }

    .dgs-proof-number-card {
      position: relative;
      min-height: clamp(145px, 8vw, 205px);
      padding: clamp(22px, 1.5vw, 34px);
      border-radius: clamp(22px, 1.4vw, 32px);
      overflow: hidden;
    }

    .dgs-proof-number-card strong {
      display: block;
      color: #ffffff;
      font-size: clamp(34px, 2.35vw, 58px);
      line-height: 1;
      font-weight: 950;
      letter-spacing: -1.2px;
      margin-bottom: 10px;
    }

    .dgs-proof-number-card p {
      margin: 0;
      color: rgba(203,213,225,0.68);
      font-size: clamp(13px, .8vw, 16px);
    }

    .dgs-proof-image-card {
      position: relative;
      padding: clamp(16px, 1vw, 24px);
      border-radius: var(--dgs-radius);
      overflow: hidden;
    }

    .dgs-image-glow {
      position: absolute;
      inset: -40%;
      background:
        radial-gradient(circle at 20% 20%, rgba(56,189,248,.20), transparent 28%),
        radial-gradient(circle at 80% 80%, rgba(37,99,235,.16), transparent 32%);
      animation: dgsImageGlow 7s ease-in-out infinite alternate;
    }

    @keyframes dgsImageGlow {
      from { transform: translate3d(-3%, -2%, 0) scale(1); }
      to { transform: translate3d(3%, 2%, 0) scale(1.05); }
    }

    .dgs-proof-image-card img {
      position: relative;
      z-index: 2;
      width: 100%;
      display: block;
      border-radius: clamp(18px, 1.2vw, 30px);
      background: #ffffff;
      border: 1px solid rgba(255,255,255,.14);
    }

    .dgs-proof-image-footer {
      position: relative;
      z-index: 2;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      margin-top: 16px;
      padding: 16px 18px;
      border-radius: 22px;
      background: rgba(2,6,23,.58);
      border: 1px solid rgba(148,163,184,.18);
    }

    .dgs-proof-image-footer span {
      color: rgba(203,213,225,.68);
      font-size: clamp(12px, .76vw, 15px);
      font-weight: 800;
    }

    .dgs-proof-image-footer strong {
      color: #e0f2fe;
      font-size: clamp(13px, .82vw, 17px);
      font-weight: 900;
      text-align: right;
    }

    .dgs-flow-head {
      display: grid;
      grid-template-columns: minmax(0, .95fr) minmax(360px, .75fr);
      gap: clamp(28px, 4vw, 86px);
      align-items: end;
      margin-bottom: clamp(38px, 4vw, 78px);
    }

    .dgs-flow-copy {
      margin: 0;
      max-width: 760px;
    }

    .dgs-flow-grid {
      display: grid;
      gap: clamp(18px, 1.4vw, 28px);
    }

    .dgs-flow-card {
      position: relative;
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: clamp(20px, 2vw, 42px);
      align-items: center;
      padding: clamp(22px, 1.55vw, 38px);
      min-height: clamp(132px, 7vw, 185px);
      border-radius: var(--dgs-radius);
      background: linear-gradient(145deg, rgba(15,23,42,.94), rgba(2,6,23,.82));
      border: 1px solid rgba(148,163,184,.22);
      box-shadow: 0 28px 90px rgba(0,0,0,.38);
      overflow: hidden;
    }

    .dgs-flow-card::before {
      content: "";
      position: absolute;
      inset: 0 auto 0 0;
      width: var(--score);
      background: linear-gradient(90deg, rgba(56,189,248,.20), rgba(139,92,246,.16), rgba(37,99,235,.18));
      border-radius: inherit;
      transform-origin: left;
      transform: scaleX(0);
    }

    .dgs-flow-card.dgs-flow-active::before {
      animation: dgsFlowFill 1.25s ease forwards;
    }

    @keyframes dgsFlowFill {
      from { transform: scaleX(0); }
      to { transform: scaleX(1); }
    }

    .dgs-flow-main {
      position: relative;
      z-index: 2;
      display: grid;
      grid-template-columns: auto minmax(0, 1fr);
      gap: clamp(16px, 1.2vw, 26px);
      align-items: center;
    }

    .dgs-flow-icon {
      width: clamp(52px, 3.3vw, 76px);
      height: clamp(52px, 3.3vw, 76px);
      border-radius: clamp(18px, 1.2vw, 28px);
    }

    .dgs-flow-card h3 {
      margin: 0 0 8px;
      color: #ffffff;
      font-size: clamp(20px, 1.25vw, 30px);
      line-height: 1.18;
      letter-spacing: -.7px;
      font-weight: 950;
      text-align: left;
    }

    .dgs-flow-card p {
      margin: 0;
      max-width: 760px;
      color: rgba(226,232,240,.74);
      font-size: clamp(13px, .82vw, 16px);
      line-height: 1.65;
      text-align: left;
    }

    .dgs-flow-score {
      position: relative;
      z-index: 2;
      min-width: clamp(70px, 5vw, 110px);
      color: #e0f2fe;
      font-size: clamp(24px, 1.8vw, 44px);
      font-weight: 950;
      text-align: right;
    }

    .dgs-flow-bar {
      position: absolute;
      left: clamp(24px, 1.8vw, 44px);
      right: clamp(24px, 1.8vw, 44px);
      bottom: clamp(16px, 1vw, 24px);
      height: 6px;
      border-radius: 999px;
      background: rgba(255,255,255,.10);
      overflow: hidden;
      z-index: 3;
    }

    .dgs-flow-bar span {
      display: block;
      width: var(--score);
      height: 100%;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--dgs-blue), var(--dgs-purple), var(--dgs-blue));
      transform: scaleX(0);
      transform-origin: left;
    }

    .dgs-service-layout {
      display: grid;
      grid-template-columns: minmax(330px, .72fr) minmax(0, 1.28fr);
      gap: clamp(28px, 3.4vw, 78px);
      align-items: start;
    }

    .dgs-service-intro {
      position: sticky;
      top: 110px;
      padding: clamp(30px, 2.4vw, 58px);
      border-radius: var(--dgs-radius);
      text-align: left;
    }

    .dgs-service-stack {
      display: grid;
      gap: clamp(18px, 1.4vw, 30px);
    }

    .dgs-service-row {
      display: grid;
      grid-template-columns: auto minmax(0, 1fr) auto;
      gap: clamp(18px, 1.6vw, 34px);
      align-items: center;
      min-height: clamp(154px, 8.8vw, 218px);
      padding: clamp(22px, 1.8vw, 44px);
      border-radius: var(--dgs-radius);
      transition: .35s ease;
    }

    .dgs-service-row:hover {
      transform: translateY(-8px);
      border-color: rgba(56,189,248,.36) !important;
    }

    .dgs-service-no {
      width: clamp(70px, 4.8vw, 108px);
      height: clamp(70px, 4.8vw, 108px);
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: clamp(22px, 1.4vw, 32px);
      color: #ffffff;
      font-size: clamp(22px, 1.55vw, 36px);
      line-height: 1;
      font-weight: 950;
      background: linear-gradient(135deg, rgba(56,189,248,.24), rgba(139,92,246,.19), rgba(37,99,235,.18));
      border: 1px solid rgba(255,255,255,.16);
    }

    .dgs-service-content h3 {
      margin: 0 0 10px;
